chapters.body:
认证和授权
JWT (JSON Web Token) 认证
JWT 就像是一张"数字身份证"，包含了用户的身份信息，并且可以验证真伪。
// JWT 的结构
// Header.Payload.Signature

// 登录流程
POST /api/auth/login
{
 "email": "user@example.com",
 "password": "password123"
}

// 响应
{
 "success": true,
 "data": {
 "token": "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9...",
 "user": {
 "id": 123,
 "name": "张三",
 "email": "user@example.com"
 }
 }
}

// 后续请求携带 Token
GET /api/users/profile
Authorization: Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9...
OAuth 2.0 集成
// 第三方登录流程
GET /api/auth/google/redirect
// 重定向到 Google 授权页面

// 回调处理
GET /api/auth/google/callback?code=authorization_code
// 返回应用 Token
API 限流和配额
请求频率限制
javascript// 响应头中包含限流信息
HTTP/1.1 200 OK
X-RateLimit-Limit: 1000 // 每小时限制1000次请求
X-RateLimit-Remaining: 999 // 剩余请求次数
X-RateLimit-Reset: 1642694400 // 重置时间戳

// 超出限制时的响应
HTTP/1.1 429 Too Many Requests
{
 "success": false,
 "error": {
 "code": "RATE_LIMIT_EXCEEDED",
 "message": "请求过于频繁，请稍后再试",
 "retryAfter": 3600 // 建议等待时间（秒）
 }
}
数据缓存策略
HTTP 缓存头
// 设置缓存策略
GET /api/users/123
Cache-Control: public, max-age=3600 // 缓存1小时
ETag: "a1b2c3d4e5f6" // 资源版本标识

// 条件请求
GET /api/users/123
If-None-Match: "a1b2c3d4e5f6"

// 如果资源未变化
HTTP/1.1 304 Not Modified
Redis 缓存示例
// 缓存策略伪代码
async function getUser(userId) {
 // 1. 先检查缓存
 const cached = await redis.get(`user:${userId}`);
 if (cached) {
 return JSON.parse(cached);
 }

 // 2. 缓存未命中，查询数据库
 const user = await database.findUser(userId);

 // 3. 将结果缓存
 await redis.setex(`user:${userId}`, 3600, JSON.stringify(user));

 return user;
}
微服务架构中的 API
服务间通信
API 网关模式
// API 网关路由配置
{
 "routes": [
 {
 "path": "/api/users/*",
 "service": "user-service",
 "url": "http://user-service:3001"
 },
 {
 "path": "/api/orders/*", 
 "service": "order-service",
 "url": "http://order-service:3002"
 }
 ]
}
GraphQL vs REST
REST API 的局限性
// REST: 需要多次请求获取相关数据
GET /api/users/123 // 获取用户信息
GET /api/users/123/posts // 获取用户发布的文章
GET /api/posts/456/comments // 获取文章评论
GraphQL 的优势
// GraphQL: 一次请求获取所需数据
query {
 user(id: 123) {
 name
 email
 posts {
 title
 comments {
 content
 author
 }
 }
 }
}

用户管理 API 设计
让我们设计一个完整的用户管理系统 API，这是最常见的应用场景。
API 端点设计
// 用户相关操作
GET /api/users # 获取用户列表
GET /api/users/{id} # 获取特定用户
POST /api/users # 创建新用户
PUT /api/users/{id} # 更新用户信息
DELETE /api/users/{id} # 删除用户

// 用户订单相关操作
GET /api/users/{id}/orders # 获取用户的订单列表
POST /api/users/{id}/orders # 为用户创建订单
GET /api/orders/{orderId} # 获取特定订单详情
完整的 CRUD 操作
1. 创建用户（Create）
// 请求
POST /api/users
Content-Type: application/json

{
 "name": "王五",
 "email": "wangwu@example.com",
 "phone": "13800000000",
 "address": {
 "city": "上海",
 "street": "南京路100号"
 }
}

// 成功响应（状态码：201 Created）
{
 "success": true,
 "data": {
 "id": 125,
 "name": "王五",
 "email": "wangwu@example.com",
 "phone": "13800000000",
 "address": {
 "city": "上海", 
 "street": "南京路100号"
 },
 "createdAt": "2024-01-15T10:00:00Z",
 "updatedAt": "2024-01-15T10:00:00Z"
 },
 "message": "用户创建成功"
}
2. 读取用户（Read）
// 获取用户列表
GET /api/users?page=1&limit=5&sort=createdAt&order=desc

// 响应（状态码：200 OK）
{
 "success": true,
 "data": [
 {
 "id": 125,
 "name": "王五",
 "email": "wangwu@example.com",
 "createdAt": "2024-01-15T10:00:00Z"
 },
 {
 "id": 124,
 "name": "李四",
 "email": "lisi@example.com", 
 "createdAt": "2024-01-15T09:00:00Z"
 }
 ],
 "pagination": {
 "currentPage": 1,
 "totalPages": 3,
 "totalItems": 15,
 "itemsPerPage": 5
 }
}

// 获取特定用户
GET /api/users/125

// 响应
{
 "success": true,
 "data": {
 "id": 125,
 "name": "王五",
 "email": "wangwu@example.com",
 "phone": "13800000000",
 "address": {
 "city": "上海",
 "street": "南京路100号"
 },
 "createdAt": "2024-01-15T10:00:00Z",
 "updatedAt": "2024-01-15T10:00:00Z"
 }
}
3. 更新用户（Update）
// 请求
PUT /api/users/125
Content-Type: application/json

{
 "name": "王五",
 "email": "wangwu.new@example.com",
 "phone": "13900000000",
 "address": {
 "city": "深圳",
 "street": "科技园路200号"
 }
}

// 响应（状态码：200 OK）
{
 "success": true,
 "data": {
 "id": 125,
 "name": "王五",
 "email": "wangwu.new@example.com",
 "phone": "13900000000",
 "address": {
 "city": "深圳",
 "street": "科技园路200号"
 },
 "createdAt": "2024-01-15T10:00:00Z",
 "updatedAt": "2024-01-15T11:30:00Z"
 },
 "message": "用户信息更新成功"
}
4. 删除用户（Delete）
// 请求
DELETE /api/users/125

// 响应（状态码：200 OK）
{
 "success": true,
 "message": "用户删除成功"
}

// 如果用户不存在（状态码：404 Not Found）
{
 "success": false,
 "error": {
 "code": "USER_NOT_FOUND", 
 "message": "用户不存在"
 }
}
错误处理
数据验证错误
// 请求（邮箱格式错误）
POST /api/users
{
 "name": "",
 "email": "invalid-email",
 "phone": "123"
}

// 响应（状态码：400 Bad Request）
{
 "success": false,
 "error": {
 "code": "VALIDATION_ERROR",
 "message": "数据验证失败",
 "details": [
 {
 "field": "name",
 "message": "姓名不能为空"
 },
 {
 "field": "email", 
 "message": "邮箱格式不正确"
 },
 {
 "field": "phone",
 "message": "手机号格式不正确"
 }
 ]
 }
}
资源不存在错误
// 请求
GET /api/users/999

// 响应（状态码：404 Not Found）
{
 "success": false,
 "error": {
 "code": "USER_NOT_FOUND",
 "message": "用户不存在"
 }
}
使用 JavaScript 调用 API
实例

examples:
// 使用 fetch API 调用 RESTful API

// 1. 获取用户列表
async function getUsers() {
  try {
    const response = await fetch('/api/users');
    const result = await response.json();
    
    if (result.success) {
      console.log('用户列表:', result.data);
    } else {
      console.error('获取失败:', result.error.message);
    }
  } catch (error) {
    console.error('网络错误:', error);
  }
}

// 2. 创建新用户
async function createUser(userData) {
  try {
    const response = await fetch('/api/users', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(userData)
    });
    
    const result = await response.json();
    
    if (result.success) {
      console.log('用户创建成功:', result.data);
    } else {
      console.error('创建失败:', result.error.message);
    }
  } catch (error) {
    console.error('网络错误:', error);
  }
}

// 3. 更新用户信息
async function updateUser(userId, userData) {
  try {
    const response = await fetch(`/api/users/${userId}`, {
      method: 'PUT',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(userData)
    });
    
    const result = await response.json();
    
    if (result.success) {
      console.log('用户更新成功:', result.data);
    } else {
      console.error('更新失败:', result.error.message);
    }
  } catch (error) {
    console.error('网络错误:', error);
  }
}

// 4. 删除用户
async function deleteUser(userId) {
  try {
    const response = await fetch(`/api/users/${userId}`, {
      method: 'DELETE'
    });
    
    const result = await response.json();
    
    if (result.success) {
      console.log('用户删除成功');
    } else {
      console.error('删除失败:', result.error.message);
    }
  } catch (error) {
    console.error('网络错误:', error);
  }
}

chapters.body:
使用工具测试 API
1. Postman 测试
Postman 是最流行的 API 测试工具，就像是 API 的"试验场"。
Postman 官网地址：https://www.postman.com/。
基本测试步骤：
创建新请求
设置 HTTP 方法（GET、POST 等）
输入 API 地址
添加请求头和请求体
发送请求查看响应
Postman 集合示例：
{
 "info": {
 "name": "用户管理 API 测试",
 "description": "测试用户相关的所有 API 端点"
 },
 "item": [
 {
 "name": "获取用户列表",
 "request": {
 "method": "GET",
 "header": [],
 "url": {
 "raw": "{{baseUrl}}/api/users?page=1&limit=10",
 "host": ["{{baseUrl}}"],
 "path": ["api", "users"],
 "query": [
 {"key": "page", "value": "1"},
 {"key": "limit", "value": "10"}
 ]
 }
 }
 }
 ]
}
2. curl 命令行测试
# 获取用户列表
curl -X GET "https://api.example.com/users" \
 -H "Content-Type: application/json"

# 创建新用户
curl -X POST "https://api.example.com/users" \
 -H "Content-Type: application/json" \
 -d '{
 "name": "张三",
 "email": "zhangsan@example.com"
 }'

# 更新用户信息
curl -X PUT "https://api.example.com/users/123" \
 -H "Content-Type: application/json" \
 -d '{
 "name": "李四",
 "email": "lisi@example.com"
 }'

# 删除用户
curl -X DELETE "https://api.example.com/users/123" \
 -H "Content-Type: application/json"
3. 浏览器开发者工具
// 在浏览器控制台中测试
fetch('/api/users', {
 method: 'GET',
 headers: {
 'Content-Type': 'application/json'
 }
})
.then(response => response.json())
.then(data => console.log(data))
.catch(error => console.error('Error:', error));
常见问题调试
1. CORS 跨域问题
报错信息：
Access to fetch at 'https://api.example.com/users' from origin 'http://localhost:3000' 
has been blocked by CORS policy
解决方案：
// 服务器端需要设置 CORS 头
app.use((req, res, next) => {
 res.header('Access-Control-Allow-Origin', '*');
 res.header('Access-Control-Allow-Methods', 'GET,PUT,POST,DELETE');
 res.header('Access-Control-Allow-Headers', 'Content-Type, Authorization');
 next();
});
2. 状态码错误
常见错误及原因：
状态码
可能原因
解决方法
400
请求数据格式错误
检查 JSON 格式和必填字段
401
身份验证失败
检查 Token 是否正确
404
API 路径错误
确认 URL 拼写正确
500
服务器内部错误
查看服务器日志
3. 数据格式问题
// 错误的请求格式
{
 name: "张三", // &#x274c; 缺少引号
 'email': "test@example.com", // &#x274c; 单引号
 age: "25" // &#x274c; 数字用了字符串
}

// 正确的请求格式
{
 "name": "张三", // &#x2705; 双引号
 "email": "test@example.com", // &#x2705; 双引号
 "age": 25 // &#x2705; 数字类型
}
自动化测试
单元测试示例
实例

examples:
// 使用 Jest 测试框架
describe('用户 API 测试', () => {
  test('应该能够获取用户列表', async () => {
    const response = await fetch('/api/users');
    const data = await response.json();
    
    expect(response.status).toBe(200);
    expect(data.success).toBe(true);
    expect(Array.isArray(data.data)).toBe(true);
  });
  
  test('应该能够创建新用户', async () => {
    const newUser = {
      name: "测试用户",
      email: "test@example.com"
    };
    
    const response = await fetch('/api/users', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify(newUser)
    });
    
    const data = await response.json();
    
    expect(response.status).toBe(201);
    expect(data.success).toBe(true);
    expect(data.data.name).toBe(newUser.name);
  });
});

chapters.body:
JSON 格式
现代 RESTful API 主要使用 JSON（JavaScript Object Notation）格式来传输数据。
JSON 就像是数据的"通用语言"，简单易读。
JSON 基础语法
{
 "name": "张三",
 "age": 25,
 "email": "zhangsan@example.com",
 "hobbies": ["阅读", "游泳", "编程"],
 "address": {
 "city": "北京",
 "district": "朝阳区"
 },
 "isActive": true
}
请求格式
GET 请求示例:
// 请求
GET /api/users/123
Accept: application/json

// 响应
{
 "id": 123,
 "name": "张三",
 "email": "zhangsan@example.com",
 "createdAt": "2024-01-15T08:30:00Z"
}
POST 请求示例:
// 请求
POST /api/users
Content-Type: application/json

{
 "name": "李四",
 "email": "lisi@example.com",
 "password": "securePassword123"
}

// 响应
{
 "id": 124,
 "name": "李四",
 "email": "lisi@example.com",
 "createdAt": "2024-01-15T09:00:00Z",
 "message": "用户创建成功"
}
响应结构设计
统一的响应格式
{
 "success": true,
 "data": {
 "id": 123,
 "name": "张三"
 },
 "message": "操作成功",
 "timestamp": "2024-01-15T08:30:00Z"
}
错误响应格式
{
 "success": false,
 "error": {
 "code": "VALIDATION_ERROR",
 "message": "输入数据验证失败",
 "details": [
 {
 "field": "email",
 "message": "邮箱格式不正确"
 }
 ]
 },
 "timestamp": "2024-01-15T08:30:00Z"
}
分页响应
{
 "success": true,
 "data": [
 {
 "id": 1,
 "name": "用户1"
 },
 {
 "id": 2,
 "name": "用户2"
 }
 ],
 "pagination": {
 "currentPage": 1,
 "totalPages": 10,
 "totalItems": 100,
 "itemsPerPage": 10
 }
}
请求头常用字段
字段名
作用
示例
Content-Type
请求体数据格式
application/json
Accept
期望的响应格式
application/json
Authorization
身份验证信息
Bearer token123
User-Agent
客户端信息
MyApp/1.0
